def test_run_subprocess_wraps_file_not_found(monkeypatch):
    def fake_subprocess_run(_command, **_kwargs):
        raise FileNotFoundError(2, "No such file or directory", "/missing/blender")

    monkeypatch.setattr(bridge_runner.subprocess, "run", fake_subprocess_run)

    with pytest.raises(bridge_runner.RunnerError, match="Executable not found"):
        bridge_runner._run_subprocess(["/missing/blender", "--version"])


def test_resolve_apptainer_executable_uses_fallback_paths(monkeypatch):
    monkeypatch.setattr(bridge_runner.shutil, "which", lambda _name: None)
    monkeypatch.setattr(
        bridge_runner.Path,
        "is_file",
        lambda self: str(self) == "/usr/bin/apptainer",
        raising=False,
    )
    monkeypatch.setattr(
        bridge_runner.os,
        "access",
        lambda path, _mode: str(path) == "/usr/bin/apptainer",
    )

    assert bridge_runner._resolve_apptainer_executable() == "/usr/bin/apptainer"


def test_slurm_mode_returns_job_id_and_poll_completion(monkeypatch, payload_file: Path, tmp_path: Path):
    args = _base_args(payload_file, tmp_path)
    args.command = "slurm"
    args.poll = True
    args.output_name = "done.png"

    expected_output = Path(args.output_dir) / args.output_name
    expected_output.parent.mkdir(parents=True, exist_ok=True)
    expected_output.write_bytes(b"png")

    responses = [
        CompletedProcess(["sbatch"], 0, stdout="12345\n", stderr=""),
        CompletedProcess(["squeue"], 0, stdout="RUNNING\n", stderr=""),
        CompletedProcess(["squeue"], 0, stdout="", stderr=""),
    ]

    def fake_run(_command):
        return responses.pop(0)

    monkeypatch.setattr(bridge_runner, "_run_subprocess", fake_run)
    monkeypatch.setattr(bridge_runner.time, "sleep", lambda _seconds: None)

    result = bridge_runner.run_slurm(args)

    assert result["job_id"] == "12345"
    assert result["status"] == "completed"


def test_interactive_mode_wraps_local_runner_invocation(
    monkeypatch, payload_file: Path, tmp_path: Path
):
    args = _base_args(payload_file, tmp_path)
    args.command = "interactive"
    args.output_name = "interactive.png"

    calls = []
    out_path = Path(args.output_dir) / args.output_name
    stdout = "\n".join(
        [
            "allocation granted",
            json.dumps(
                {
                    "status": "completed",
                    "mode": "local",
                    "run_id": "testrun",
                    "output_png": str(out_path),
                    "output_dir": str(out_path.parent),
                }
            ),
        ]
    )

    def fake_run(command, *, env=None):
        calls.append(command)
        return CompletedProcess(command, 0, stdout=stdout, stderr="")

    monkeypatch.setattr(bridge_runner, "_run_subprocess", fake_run)
    monkeypatch.chdir(tmp_path)

    result = bridge_runner.run_interactive(args)

    assert result["status"] == "completed"
    assert result["mode"] == "interactive"
    assert calls
    command = calls[0]
    assert command[:3] == ["qlogin", "-p", "gpu"]
    script_path = Path(result["script_path"])
    assert script_path.is_file()
    script_text = script_path.read_text(encoding="utf-8")
    assert "bridge_runner.py" in script_text
    assert " local " in script_text or " local\n" in script_text


def test_interactive_open_qlogin_returns_ready(monkeypatch, payload_file: Path, tmp_path: Path):
    args = _base_args(payload_file, tmp_path)
    args.backend = "qlogin"
    args.session_id = "sess_open"
    args.output_dir = str(tmp_path / "interactive_out")
    args.poll_interval = 1
    args.startup_timeout = 2

    monkeypatch.setattr(bridge_runner, "SESSION_ROOT", tmp_path / "sessions")

    class _DummyProcess:
        pid = 4242

        @staticmethod
        def poll():
            return None

    monkeypatch.setattr(bridge_runner.subprocess, "Popen", lambda *a, **k: _DummyProcess())
    monkeypatch.setattr(
        bridge_runner,
        "_load_session_record",
        lambda _sid: {
            "session_id": "sess_open",
            "status": "ready",
            "worker_pid": 4242,
            "backend": "qlogin",
            "default_output_dir": str(tmp_path / "interactive_out"),
        },
    )

    result = bridge_runner.run_interactive_open(args)

    assert result["status"] == "ready"
    assert result["backend"] == "qlogin"
    assert result["session_id"] == "sess_open"


def test_interactive_submit_qlogin_reads_result_file(monkeypatch, payload_file: Path, tmp_path: Path):
    args = _base_args(payload_file, tmp_path)
    args.command = "interactive-submit"
    args.session_id = "sess_submit"
    args.poll = True
    args.poll_interval = 1

    monkeypatch.setattr(bridge_runner, "SESSION_ROOT", tmp_path / "sessions")
    session_dir = bridge_runner.SESSION_ROOT / args.session_id
    for child in ("requests", "results", "control", "staged"):
        (session_dir / child).mkdir(parents=True, exist_ok=True)
    bridge_runner._write_json_atomic(
        session_dir / "session.json",
        {
            "session_id": args.session_id,
            "backend": "qlogin",
            "status": "ready",
            "worker_pid": 999,
            "default_output_dir": str(tmp_path / "interactive_out"),
        },
    )

    monkeypatch.setattr(bridge_runner, "_session_pid_alive", lambda _pid: True)
    monkeypatch.setattr(bridge_runner, "_new_run_id", lambda: "req123")
    bridge_runner._write_json_atomic(
        session_dir / "results" / "req123.json",
        {
            "status": "completed",
            "mode": "interactive",
            "run_id": "testrun",
            "output_png": str(tmp_path / "interactive_out" / "done.png"),
            "output_dir": str(tmp_path / "interactive_out"),
        },
    )

    result = bridge_runner.run_interactive_submit(args)

    assert result["status"] == "completed"
    assert result["session_id"] == "sess_submit"
    assert result["request_id"] == "req123"


def test_interactive_submit_jobid_uses_saved_launcher(monkeypatch, payload_file: Path, tmp_path: Path):
    args = _base_args(payload_file, tmp_path)
    args.command = "interactive-submit"
    args.session_id = "sess_jobid"
    args.output_name = "jobid.png"

    monkeypatch.setattr(bridge_runner, "SESSION_ROOT", tmp_path / "sessions")
    session_dir = bridge_runner.SESSION_ROOT / args.session_id
    for child in ("requests", "results", "control", "staged"):
        (session_dir / child).mkdir(parents=True, exist_ok=True)
    bridge_runner._write_json_atomic(
        session_dir / "session.json",
        {
            "session_id": args.session_id,
            "backend": "jobid",
            "status": "ready",
            "job_id": "555",
            "job_launcher": "srun --jobid {job_id}",
            "default_output_dir": str(tmp_path / "interactive_out"),
        },
    )

    captured = {}

    def fake_one_shot(one_shot_args):
        captured["launcher"] = one_shot_args.interactive_launcher
        return {"status": "completed", "output_png": str(tmp_path / "interactive_out" / "jobid.png")}

    monkeypatch.setattr(bridge_runner, "run_interactive", fake_one_shot)

    result = bridge_runner.run_interactive_submit(args)

    assert result["status"] == "completed"
    assert result["backend"] == "jobid"
    assert captured["launcher"] == "srun --jobid 555"


def test_interactive_close_marks_session_closed(monkeypatch, payload_file: Path, tmp_path: Path):
    args = _base_args(payload_file, tmp_path)
    args.command = "interactive-close"
    args.session_id = "sess_close"
    args.wait = False
    args.force = False

    monkeypatch.setattr(bridge_runner, "SESSION_ROOT", tmp_path / "sessions")
    session_dir = bridge_runner.SESSION_ROOT / args.session_id
    for child in ("requests", "results", "control", "staged"):
        (session_dir / child).mkdir(parents=True, exist_ok=True)
    bridge_runner._write_json_atomic(
        session_dir / "session.json",
        {
            "session_id": args.session_id,
            "backend": "qlogin",
            "status": "ready",
            "worker_pid": 777,
        },
    )
    monkeypatch.setattr(bridge_runner, "_session_pid_alive", lambda _pid: False)

    result = bridge_runner.run_interactive_close(args)

    assert result["status"] == "closed"
    refreshed = bridge_runner._load_json(session_dir / "session.json")
    assert refreshed["status"] == "closed"
